const { createClient } = require('@supabase/supabase-js');
const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);
async function check() {
  // Get total count
  const { count: totalCount } = await supabase
    .from('events')
    .select('id', { count: 'exact', head: true })
    .eq('status', 'published');

  console.log('Total events in DB:', totalCount);

  // Get all events with their sources
  const { data: allEvents } = await supabase
    .from('events')
    .select('id, title_en, source')
    .eq('status', 'published')
    .limit(20);

  console.log('\\nAll events (sample):');
  console.log(JSON.stringify(allEvents, null, 2));

  // Group by source
  const sourceGroups = {};
  const { data: allWithSource } = await supabase
    .from('events')
    .select('source')
    .eq('status', 'published');

  (allWithSource || []).forEach(e => {
    sourceGroups[e.source] = (sourceGroups[e.source] || 0) + 1;
  });
  console.log('\\nSource distribution:', JSON.stringify(sourceGroups, null, 2));
}
check().catch(console.error);
"
